"""Choose two connected Native left-turn paths from a surveyed junction.

The caller supplies paths from actual map waypoint successors. This selector
does not assert that a chosen map and physical turn satisfy the statute.
"""

from math import hypot, isfinite


def _unit(vector):
    if len(vector) != 2 or not all(isinstance(v, (int, float)) and isfinite(v) for v in vector):
        raise ValueError('route heading needs finite XY components')
    length = hypot(*vector)
    if length < 1e-6:
        raise ValueError('zero route heading')
    return (vector[0]/length, vector[1]/length)


def _left(route):
    start, end = _unit(route['approach_heading_xy']), _unit(route['exit_heading_xy'])
    cross = start[0]*end[1]-start[1]*end[0]
    dot = start[0]*end[0]+start[1]*end[1]
    return cross > .5 and abs(dot) < .8


def select_opposing_left_pair(routes, lane_inventory, *, route_accept=None):
    """Return a same-junction opposing pair with opposite-sign road lanes.

    `routes` contain connected Native waypoint `path`, approach/exit road IDs,
    axis identity and measured headings. `lane_inventory` maps each road ID to
    original Native lane IDs. A caller may reject unsuitable junction geometry
    or devices using `route_accept`, but cannot relax the checks here.
    """
    for route in routes:
        if not route.get('path') or route.get('junction_id') is None:
            raise ValueError('route lacks connected Native path or junction')
    for a in routes:
        for b in routes:
            if a is b or a['junction_id'] != b['junction_id'] or (
                    a.get('approach_axis') != b.get('approach_axis')):
                continue
            if not (_left(a) and _left(b)):
                continue
            if ('approach_lane_id' in a and 'approach_lane_id' in b and
                    a['approach_lane_id'] * b['approach_lane_id'] >= 0):
                continue
            heading_a, heading_b = _unit(a['approach_heading_xy']), _unit(b['approach_heading_xy'])
            if heading_a[0]*heading_b[0]+heading_a[1]*heading_b[1] > -.8:
                continue
            roads = {a['approach_road_id'], a['exit_road_id'],
                     b['approach_road_id'], b['exit_road_id']}
            if any(not (any(lane < 0 for lane in lane_inventory.get(road, ())) and
                        any(lane > 0 for lane in lane_inventory.get(road, ()))) for road in roads):
                continue
            if route_accept is not None and not route_accept(a, b):
                continue
            return {'subject': a, 'opposing': b,
                    'junction_id': a['junction_id'],
                    'selection_basis': 'connected Native left-turn successors, opposing headings and two-directional lane inventory',
                    'legal_front_of_each_other': 'unreviewed'}
    raise ValueError('no surveyed opposing two-directional left-turn pair')

"""Survey connected Native waypoint paths for an opposing left-turn pair.

This module can be imported without CARLA. The caller supplies the live Native
map; returned paths retain its waypoint objects for the eventual runner.
"""

import math
from xml.etree import ElementTree

from opposing_turn_routes import select_opposing_left_pair


def driving_lanes(opendrive):
    root = ElementTree.fromstring(opendrive)
    inventory = {}
    for road in root.findall('road'):
        lanes = set()
        for lane in road.findall('./lanes/laneSection/left/lane') + road.findall('./lanes/laneSection/right/lane'):
            if lane.get('type') == 'driving':
                lanes.add(int(lane.get('id')))
        inventory[int(road.get('id'))] = sorted(lanes)
    return inventory


def heading(waypoint):
    yaw = math.radians(float(waypoint.transform.rotation.yaw))
    return [math.cos(yaw), math.sin(yaw)]


def _key(waypoint):
    return (int(waypoint.road_id), int(waypoint.lane_id),
            round(float(waypoint.s), 2), bool(waypoint.is_junction))


def discover_routes(world_map, *, step_m=2.0, max_steps=80):
    """Follow actual successors from each spawn to an exterior left-turn exit."""
    if not 1.0 <= step_m <= 3.0 or not 10 <= max_steps <= 200:
        raise ValueError('unsupported Native waypoint survey bounds')
    inventory = driving_lanes(world_map.to_opendrive())
    routes = []
    for spawn in world_map.get_spawn_points():
        approach = world_map.get_waypoint(spawn.location)
        if approach is None or approach.is_junction:
            continue
        if not ({-1, 1} <= {1 if n > 0 else -1 for n in inventory.get(approach.road_id, [])}):
            continue
        queue = [(approach, [approach], None)]
        seen = set()
        while queue:
            waypoint, path, junction_id = queue.pop(0)
            key = (_key(waypoint), junction_id)
            if key in seen:
                continue
            seen.add(key)
            if len(path) > max_steps:
                continue
            if waypoint.is_junction:
                junction = waypoint.get_junction()
                if junction is None:
                    continue
                if junction_id is not None and junction_id != junction.id:
                    continue
                junction_id = junction.id
            elif junction_id is not None:
                start, end = heading(approach), heading(waypoint)
                cross = start[0]*end[1] - start[1]*end[0]
                dot = start[0]*end[0] + start[1]*end[1]
                exit_lanes = inventory.get(waypoint.road_id, [])
                if (cross > 0.5 and abs(dot) < 0.8 and
                        any(n < 0 for n in exit_lanes) and any(n > 0 for n in exit_lanes)):
                    routes.append({
                        'path': path, 'junction_id': junction_id,
                        'approach_axis': approach.road_id,
                        'approach_heading_xy': start, 'exit_heading_xy': end,
                        'approach_road_id': approach.road_id,
                        'approach_lane_id': approach.lane_id,
                        'exit_road_id': waypoint.road_id,
                        'exit_lane_id': waypoint.lane_id,
                    })
                continue
            for successor in waypoint.next(step_m):
                if junction_id is None and not successor.is_junction and successor.road_id != approach.road_id:
                    continue
                if _key(successor) in {_key(item) for item in path}:
                    continue
                queue.append((successor, path + [successor], junction_id))
    return routes, inventory


def choose_native_pair(world_map, *, step_m=2.0, max_steps=80, route_accept=None):
    routes, inventory = discover_routes(world_map, step_m=step_m, max_steps=max_steps)
    return select_opposing_left_pair(routes, inventory, route_accept=route_accept)

"""Original-tick geometry for simultaneous opposing left turns.

The output is a measured trajectory description, not a legal classification.
Only original Native body/heading samples and map/device inventory may be input.
"""

import json
import hashlib
from math import hypot, isfinite
from pathlib import Path


def _point(value, name):
    if not isinstance(value, (list, tuple)) or len(value) != 2 or not all(
            isinstance(x, (int, float)) and isfinite(x) for x in value):
        raise ValueError(f'{name} needs a finite XY pair')
    return (float(value[0]), float(value[1]))


def _rows(path, name):
    rows = [json.loads(line) for line in Path(path).read_text().splitlines() if line.strip()]
    if not rows:
        raise ValueError(f'missing original {name} samples')
    frames = [r.get('frame') for r in rows]
    if any(type(f) is not int for f in frames) or frames != sorted(set(frames)):
        raise ValueError(f'nonmonotonic original {name} frames')
    return {r['frame']: r for r in rows}


def _corners(value):
    if not isinstance(value, list) or len(value) < 4:
        raise ValueError('original ground-body corners are missing')
    return [_point(corner, 'ground-body corner') for corner in value]


def _segment_distance(point, a, b):
    vx, vy = b[0]-a[0], b[1]-a[1]
    squared = vx*vx+vy*vy
    if squared < 1e-12:
        return hypot(point[0]-a[0], point[1]-a[1])
    t = max(0., min(1., ((point[0]-a[0])*vx+(point[1]-a[1])*vy)/squared))
    return hypot(point[0]-(a[0]+t*vx), point[1]-(a[1]+t*vy))


def _cross(a, b, c):
    return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])


def _intersect(a, b, c, d):
    if (max(min(a[0], b[0]), min(c[0], d[0])) >
            min(max(a[0], b[0]), max(c[0], d[0])) or
            max(min(a[1], b[1]), min(c[1], d[1])) >
            min(max(a[1], b[1]), max(c[1], d[1]))):
        return False
    return _cross(a, b, c)*_cross(a, b, d) <= 0 and _cross(c, d, a)*_cross(c, d, b) <= 0


def _inside(point, polygon):
    inside = False
    for a, b in zip(polygon, polygon[1:]+polygon[:1]):
        if (a[1] > point[1]) != (b[1] > point[1]):
            crossing_x = a[0] + (point[1]-a[1])*(b[0]-a[0])/(b[1]-a[1])
            if point[0] < crossing_x:
                inside = not inside
    return inside


def _body_clearance(a, b):
    edges_a = list(zip(a, a[1:]+a[:1]))
    edges_b = list(zip(b, b[1:]+b[:1]))
    if (any(_intersect(p, q, r, s) for p, q in edges_a for r, s in edges_b) or
            _inside(a[0], b) or _inside(b[0], a)):
        return 0.
    return min([_segment_distance(p, r, s) for p in a for r, s in edges_b] +
               [_segment_distance(p, r, s) for p in b for r, s in edges_a])


def measure(subject_path, opposing_path, topology_path, device_path):
    """Return per-tick relative geometry while both vehicles turn in the junction.

    Heading is the measured front direction, not an inferred route label. The
    nearest-center tick and signed projections preserve information needed for
    a later independent front/behind review without declaring a legal cutoff.
    """
    topology = json.loads(Path(topology_path).read_text())
    devices = json.loads(Path(device_path).read_text())
    if not topology.get('both_highways_two_directional'):
        raise ValueError('original map inventory does not establish two-directional highways')
    if not topology.get('same_intersection') or not topology.get('opposing_approaches'):
        raise ValueError('original map inventory does not establish opposing approaches')
    if 'governing_device' not in devices or devices['governing_device'] not in (
            'none', 'directs_alternate', 'unresolved'):
        raise ValueError('original governing-device inventory is missing')
    subject = _rows(subject_path, 'subject')
    opposing = _rows(opposing_path, 'opposing')
    if subject.keys() != opposing.keys():
        raise ValueError('subject and opposing original frame sets differ')
    observations = []
    previous_time = None
    for frame in subject:
        a, b = subject[frame], opposing[frame]
        ta, tb = a.get('time_s'), b.get('time_s')
        if not all(isinstance(v, (int, float)) and isfinite(v) for v in (ta, tb)):
            raise ValueError('missing original frame times')
        if abs(ta-tb) > 1e-6 or (previous_time is not None and ta <= previous_time):
            raise ValueError('original turn sources are not time joined')
        previous_time = ta
        if not (a.get('in_intersection') and b.get('in_intersection') and
                a.get('turning_left') and b.get('turning_left')):
            continue
        pa, pb = _point(a.get('center_xy'), 'subject center'), _point(b.get('center_xy'), 'opposing center')
        ha, hb = _point(a.get('heading_xy'), 'subject heading'), _point(b.get('heading_xy'), 'opposing heading')
        corners_a, corners_b = _corners(a.get('ground_corners_xy')), _corners(b.get('ground_corners_xy'))
        na, nb = hypot(*ha), hypot(*hb)
        if na < 1e-6 or nb < 1e-6:
            raise ValueError('zero measured heading')
        dx, dy = pb[0]-pa[0], pb[1]-pa[1]
        observations.append({
            'frame': frame, 'time_s': float(ta), 'center_distance_m': hypot(dx, dy),
            'ground_body_clearance_m': _body_clearance(corners_a, corners_b),
            'opposing_ahead_of_subject_m': (dx*ha[0]+dy*ha[1])/na,
            'subject_ahead_of_opposing_m': (-dx*hb[0]-dy*hb[1])/nb,
            'opposing_left_of_subject_m': (ha[0]*dy-ha[1]*dx)/na,
            'subject_left_of_opposing_m': (hb[1]*dx-hb[0]*dy)/nb,
        })
    if len(observations) < 2:
        raise ValueError('no sustained simultaneous original left-turn interval')
    closest = min(observations, key=lambda r: r['center_distance_m'])
    source_refs = [{'path': str(Path(path)),
                    'sha256': hashlib.sha256(Path(path).read_bytes()).hexdigest()}
                   for path in (subject_path, opposing_path, topology_path, device_path)]
    return {
        'format': 'opposing-left-turn-original-geometry-v1',
        'law_id': 'NRS-484B-400-2c', 'governing_device': devices['governing_device'],
        'simultaneous_frames': len(observations), 'first_frame': observations[0]['frame'],
        'last_frame': observations[-1]['frame'], 'closest': closest,
        'observations': observations, 'legal_front_of_each_other': 'unreviewed',
        'physical_completion': 'unreviewed',
        'source_refs': source_refs,
    }

"""Four original-frame RGB sources for the one-way-to-two-way turn delivery attempt.

The caller owns the world and encoder sinks. Each sensor is attached to the
subject; a sink must retain its own unscaled source stream under the given name.
This module does not infer actual curb/centerline visibility from pixels.
"""
from __future__ import annotations

from dataclasses import dataclass
import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-8.0, 0.0, 8.0), (-12.0, 0.0, 0.0), (1920, 1080), 95),
    "approach": ((1.2, 0.0, 2.0), (0.0, 0.0, 0.0), (1280, 720), 90),
    "reference_corner": ((-3.0, 2.5, 2.6), (-7.0, 0.0, 0.0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0.0, 0.0, 0.0), (1280, 720), 85),
}


@dataclass(frozen=True)
class CameraPlan:
    name: str
    location: tuple[float, float, float]
    rotation: tuple[float, float, float]
    size: tuple[int, int]
    fov: int


def plans(overview_height_delta_m=0.0):
    if not 0.0<=overview_height_delta_m<=2.0:
        raise ValueError('Unsupported overview mount change')
    result=[]
    for name,spec in CAMERAS.items():
        location,rotation,size,fov=spec
        if name=='overview':
            location=(location[0],location[1],location[2]+overview_height_delta_m)
        result.append(CameraPlan(name,location,rotation,size,fov))
    return result


class FFmpegSourceSink:
    """Retain one lossless, original-resolution BGRA stream from CARLA images."""

    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior source stream; use a fresh attempt")
        width, height = CAMERAS[name][2]
        self.size = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed:
            raise ValueError("Source stream already closed")
        raw = image.raw_data
        if len(raw) != self.size:
            raise ValueError("Source camera raw byte count changed")
        self.process.stdin.write(raw)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Source camera encoder failed")


class TurnCameraCapture:
    def __init__(self, world, carla_module, subject, sinks, overview_height_delta_m=0.0):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named source-camera sinks are required")
        self.sensors = {}
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.callback_errors = []
        self.closed = False
        library = world.get_blueprint_library()
        try:
            for plan in plans(overview_height_delta_m):
                bp = library.find("sensor.camera.rgb")
                for key, value in (("image_size_x", plan.size[0]),
                                   ("image_size_y", plan.size[1]),
                                   ("fov", plan.fov), ("sensor_tick", 0.05)):
                    bp.set_attribute(key, str(value))
                loc = carla_module.Location(*plan.location)
                pitch, yaw, roll = plan.rotation
                transform = carla_module.Transform(loc, carla_module.Rotation(pitch, yaw, roll))
                sensor = world.spawn_actor(bp, transform, attach_to=subject)
                self.sensors[plan.name] = sensor
                sensor.listen(lambda image, name=plan.name: self._on_frame(name, image))
        except BaseException:
            self.close()
            raise

    def _on_frame(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original camera frame: " + name)
                expected = CAMERAS[name][2]
                if (image.width, image.height) != expected:
                    raise ValueError("Source camera dimensions changed: " + name)
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.callback_errors.append(error)
                raise
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, timeout_s=10):
        """Join all original source pixels before writing that Native tick."""
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.callback_errors:
                    raise ValueError("Source camera callback failed") from self.callback_errors[0]
                if all(frame in rows for rows in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    missing = sorted(name for name, rows in self.frames.items() if frame not in rows)
                    raise ValueError("Timed out waiting for source camera frame "
                                     + str(frame) + ": " + ", ".join(missing))
                self.condition.wait(remaining)

    def verify_frames(self, frames):
        if self.callback_errors:
            raise ValueError("Source camera callback failed") from self.callback_errors[0]
        expected = set(frames)
        if not expected:
            raise ValueError("No captured original frames")
        for name, observed in self.frames.items():
            if observed != expected:
                raise ValueError("Missing or extra source-camera frames: " + name)
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in self.sensors.values():
                sensor.stop()
                sensor.destroy()

"""Bind a candidate official device to original Native road and signal inventory.

A map signal and operator observation are source candidates, not a legal finding
that the exception governs either opposing left turn.
"""
from hashlib import sha256
from xml.etree import ElementTree


def verify_device_candidate(opendrive_text, approach_road_ids, survey):
    if not isinstance(opendrive_text, str) or not opendrive_text.strip():
        raise ValueError('Missing original OpenDRIVE bytes')
    digest = sha256(opendrive_text.encode('utf-8')).hexdigest()
    if survey.get('opendrive_sha256') != digest:
        raise ValueError('Operator device survey is stale for the Native map')
    if survey.get('source_kind') != 'operator_observed_native_device':
        raise ValueError('Device direction needs an original operator observation')
    if not survey.get('instruction_text') or not survey.get('observation_reference'):
        raise ValueError('Device instruction or original observation reference is missing')
    if survey.get('observed_direction') != 'directs_alternate':
        raise ValueError('Operator observation does not identify alternate crossing direction')
    road_id = survey.get('road_id')
    signal_id = survey.get('signal_id')
    if road_id not in approach_road_ids or not isinstance(signal_id, str) or not signal_id:
        raise ValueError('Survey device is outside the selected approach roads')
    root = ElementTree.fromstring(opendrive_text)
    matches = []
    for road in root.findall('road'):
        if road.get('id') != str(road_id):
            continue
        for signal in road.findall('./signals/signal'):
            if signal.get('id') == signal_id:
                matches.append(signal)
    if len(matches) != 1:
        raise ValueError('Original map does not uniquely identify the surveyed device')
    return {'governing_device':'directs_alternate',
            'candidate_road_signals':[{'road_id':road_id,'signal_id':signal_id,
                                       'opendrive_sha256':digest}],
            'candidate_instruction_text':survey['instruction_text'],
            'observation_reference':survey['observation_reference'],
            'direction_claim_source':'operator observation, pending independent review',
            'legal_device_applicability':'unreviewed'}
